// Two layers live here. This package orchestrates: it builds a development CLI
// and engine out of the current source tree. The suites under testdata/ then run
// against what it built. Both import the Go client from this repo; this module
// exists to keep their test-only dependencies out of sdk/go.
//
// Orchestration reaches the engine-dev toolchain module through a client
// generated by `dagger api client` into internal/dagger/engine-dev.
//
// Generated clients are heading for one package per module, each a typed view
// over a client the caller owns (dagger/dagger#13805):
//
//	dag, err := dagger.Connect(ctx)
//	engineDev := enginedev.New(dag)
//
// This package is already written in that shape. Two things still differ, and
// both are type changes rather than shape changes, so no call site here moves
// when they land: the core client comes from enginedev.Connect rather than
// dagger.io/dagger (dagger/go-sdk#19), and core types are enginedev's own rather
// than dagger.io/dagger's (dagger/go-sdk#18).
package e2e

import (
	"os"
	"testing"

	enginedev "github.com/dagger/dagger/sdk/go/e2e/internal/dagger/engine-dev"
)

// connect opens a session and returns the core client, closed when the test ends.
//
// Connecting also serves engine-dev into the session, which is what makes this
// work under `dagger api exec`. Workspace modules normally appear in a session's
// API on their own, but the engine decides whether to include them once, when it
// first sets up a client's workspace, and caches that answer
// (ensureWorkspaceLoaded, engine/server/session_workspaces.go); `dagger api exec`
// sets us up with the built-in API only, and opting in afterwards does not re-run
// the decision. Serving by module source sidesteps that, so these tests need no
// module config of their own.
func connect(t *testing.T) *enginedev.Client {
	t.Helper()

	dag, err := enginedev.Connect(
		t.Context(),
		enginedev.WithLogOutput(os.Stderr),
	)
	if err != nil {
		t.Fatalf("connect orchestration client: %v", err)
	}
	t.Cleanup(func() {
		if err := dag.Close(); err != nil {
			t.Errorf("close orchestration client: %v", err)
		}
	})
	return dag
}

// newEngineDev returns the engine-dev module as a view over dag's session.
//
// Stands in for enginedev.New(dag). The module is already served by connect,
// because today the generated client serves it when it connects.
func newEngineDev(dag *enginedev.Client) *enginedev.EngineDev {
	return dag.EngineDev()
}

// devCLIBinary lifts the CLI out of the engine container rather than building it
// from the cli-dev toolchain module directly.
//
// cli-dev would be the honest source, but a generated client opens its own
// session, and object IDs do not cross session boundaries — which is exactly what
// mounting this file into a container needs. Lifting it out of the engine works
// because engine-dev builds the container's CLI from cli-dev anyway. Revisit once
// dagger/go-sdk#18 and dagger/go-sdk#19 land.
func devCLIBinary(engineDev *enginedev.EngineDev) *enginedev.File {
	return engineDev.Container().File("/usr/local/bin/dagger")
}

func startDevEngine(t *testing.T, engineDev *enginedev.EngineDev, name string) (*enginedev.Service, string) {
	t.Helper()

	engine, err := engineDev.Service(name).Start(t.Context())
	if err != nil {
		t.Fatalf("start development engine: %v", err)
	}
	endpoint, err := engine.Endpoint(t.Context(), enginedev.ServiceEndpointOpts{Port: 1234, Scheme: "tcp"})
	if err != nil {
		t.Fatalf("resolve development engine endpoint: %v", err)
	}
	return engine, endpoint
}

func requireTargetExec(t *testing.T, target *enginedev.Container, operation string) {
	t.Helper()
	ctx := t.Context()
	stdout, err := target.Stdout(ctx)
	if err != nil {
		t.Fatal(err)
	}
	stderr, err := target.Stderr(ctx)
	if err != nil {
		t.Fatal(err)
	}
	exitCode, err := target.ExitCode(ctx)
	if err != nil {
		t.Fatal(err)
	}

	t.Logf("%s stdout:\n%s", operation, stdout)
	if stderr != "" {
		t.Logf("%s stderr:\n%s", operation, stderr)
	}
	if exitCode != 0 {
		t.Fatalf("%s: exit code %d", operation, exitCode)
	}
}
